def solve(m):
    # Determinant via exact Gaussian elimination over Fractions,
    # with defensive handling of degenerate inputs.
    from fractions import Fraction
    if not m:
        return 1
    n = len(m)
    rows = list(m)
    if all(len(row) == 0 for row in rows):
        return 1  # degenerate matrix with no columns
    a = []
    for row in rows:
        r = []
        for j in range(n):
            v = row[j] if j < len(row) else 0
            r.append(Fraction(v))
        a.append(r)
    det = Fraction(1)
    for k in range(n):
        piv = None
        for i in range(k, n):
            if a[i][k] != 0:
                piv = i
                break
        if piv is None:
            return 0
        if piv != k:
            a[k], a[piv] = a[piv], a[k]
            det = -det
        det *= a[k][k]
        for i in range(k + 1, n):
            f = a[i][k] / a[k][k]
            if f != 0:
                for j in range(k, n):
                    a[i][j] -= f * a[k][j]
    if det.denominator == 1:
        return int(det)
    return float(det)

