def solve(n, b):
    # Convert integer n to base b (2..36) using digits 0-9 then a-z,
    # with a leading minus sign for negative n.
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    negative = n < 0
    n = abs(n)
    out = []
    while n > 0:
        out.append(digits[n % b])
        n //= b
    if negative:
        out.append('-')
