def solve(grid):
    # Count connected components of 1s (4-directional) in a grid.
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    seen = [[False] * cols for _ in range(rows)]
    count = 0
    for r in range(rows):
        for c in range(cols):
